from lib import *
S = SS('w53')
steps = [
    step("本机在用哪种拥塞控制算法:net.inet.tcp.use_newreno = 0(默认不用 NewReno),net.inet.tcp.cubic_sockets 显示当前有 407 个套接字在用 CUBIC(这个数随时间变),net.inet.tcp.pacing = 0。没有找到按套接字切换算法的 setsockopt——Linux 的 TCP_CONGESTION 在 macOS 上没有对应项,切换整个系统的算法需要 root,所以这一篇没法在本机对 Reno 和 BBR 做实测对照,而是用公式验证和纸面模拟来比较思路。", t=tl(S(1)), mark=lidx(S(1), 'net.inet.tcp.cubic_sockets', 'net.inet.tcp.use_newreno'), done=lidx(S(1), 'net.inet.tcp.pacing', 'use_newreno = 0'), kv=KV([['use_newreno', '0:默认不用 NewReno'], ['cubic_sockets', '407 个套接字在用 CUBIC'], ['按套接字切换', 'macOS 没有 TCP_CONGESTION 对应项'], ['本篇的对照', '公式 + 纸面模拟,不是 Reno / BBR 实测']], ['按套接字切换'])),
    step("验证 CUBIC 公式:W(t) = C·(t − K)³ + W_max,其中 t 是上次丢包后的时间,W_max 是丢包前的窗口,K = ³√(W_max·(1−β)/C),C = 0.4、β = 0.7,窗口以 MSS 计、时间以秒计。往返 100 ms、0.3% 丢包的 8 秒传输(36.6 MB)里找到 5 个快速恢复事件:0.51 秒 W_max 33 个 MSS,降到 23,K = 2.91 秒,丢包后 0.3 / 0.6 / 0.9 秒实测 24 / 26 / 27,公式预测 26 / 28 / 30;2.72 秒的事件 26 → 19,实测 20 / 21 / 23,预测 21 / 22 / 24;3.73 秒的事件 24 → 17,实测 18 / 20 / 21,预测 19 / 21 / 22;7.15 秒的事件 43 → 30,实测 31 / 29 / 25,预测 33 / 36 / 38(这一个后面又出了丢包导致偏差)。13 个可比较的点上相对误差中位 6%、最大 35%——量级吻合,说明本机的 CUBIC 基本按公式增长;不完全相等因为实测 cwnd 受 ACK 到达节奏和 10 ms 采样影响,窗口很小时还会切到“像 Reno 一样增长”的友好区域。", t=tl(S(2)), mark=lidx(S(2), '      0.51 s', '      2.72 s', '      3.73 s', '      7.15 s'), done=lidx(S(2), '传输 36.6 MB', '13 个可比较的点'), b=bars([['0.51 s 事件 · 0.9 s 实测', 27, '27'], ['0.51 s 事件 · 0.9 s 预测', 30, '30'], ['3.73 s 事件 · 0.9 s 实测', 21, '21'], ['3.73 s 事件 · 0.9 s 预测', 22, '22']], 30, mark=[0, 2], done=[1, 3]), kv=KV([['公式', 'W(t) = 0.4·(t − K)³ + W_max,β = 0.7'], ['可比较的点', '13 个:相对误差中位 6%,最大 35%'], ['结论', '本机的 CUBIC 基本按公式增长']], ['结论'])),
    step("Reno 的吞吐模型(Mathis 公式)与实测:稳态吞吐 ≈ MSS / RTT × 1.22 / √p。往返 100 ms、各传 6 秒:丢包率 0.1% 时实测 13.25 MB/s,公式 6.30 MB/s,实测是公式的 2.10 倍;0.3% 时 9.92 对 3.64,2.73 倍;1.0% 时 3.88 对 1.99,1.95 倍;3.0% 时 1.19 对 1.15,1.04 倍。也就是说本机的 CUBIC 在这条高时延路径上比 Reno 的公式预测快得多,丢包很多时两者接近;但各倍数并不单调(0.3% 最大),公式只是粗略的稳态估计,这里只看大致趋势。", t=tl(S(3)), mark=lidx(S(3), '      0.1%', '      0.3%', '      1.0%', '      3.0%'), done=lidx(S(3), '丢包率    实测吞吐', '丢包越少'), b=bars([['0.1% · 实测', 13.25, '13.25 MB/s'], ['0.1% · Reno 公式', 6.30, '6.30 MB/s'], ['1.0% · 实测', 3.88, '3.88 MB/s'], ['1.0% · Reno 公式', 1.99, '1.99 MB/s'], ['3.0% · 实测', 1.19, '1.19 MB/s'], ['3.0% · Reno 公式', 1.15, '1.15 MB/s']], 13.25, mark=[0, 2, 4], done=[1, 3, 5]), kv=KV([['0.1% / 0.3% / 1% / 3%', '实测 / 公式 = 2.10 / 2.73 / 1.95 / 1.04'], ['公式', 'MSS / RTT × 1.22 / √p'], ['解读', 'CUBIC 在高时延路径比 Reno 公式快']], ['解读'])),
    step("Reno、CUBIC、BBR 的行为差异(纸面模拟,不是实测):同一条 100 Mbit/s(12.5 MB/s)、往返 100 ms 的链路,窗口上限是带宽时延积(约 856 个 1460 字节的 MSS),每个 RTT 推进一步、共 600 秒。Reno 每 RTT 加 1、丢包乘 0.5;CUBIC 用上面的公式、β = 0.7;“BBR 近似”按假设直接设成“按估计带宽的 95% 发送、不因随机丢包降速”——所以它的数字是假设的结果,不是模拟出来的结论。随机丢包率 0.01% 时 Reno 1.74、CUBIC 3.25、BBR 近似 11.87 MB/s;0.10% 时 0.57、0.56、11.86;1.00% 时 0.19、0.10、11.75;3.00% 时 0.10、0.04、11.52。这个玩具模型只能说明思路:基于丢包的算法(Reno / CUBIC)把每个丢包都当成拥塞,在随机丢包多的链路(无线、长距离)上吞吐被压得很低;基于带宽和 RTT 测量建模的算法(BBR)对随机丢包不敏感。我写的玩具 CUBIC 在高丢包下比 Reno 还差,不代表真实 CUBIC;BBR 真实的公平性、队列长度表现模拟里完全没有体现。", t=tl(S(4)), mark=lidx(S(4), '   0.01%', '   0.10%', '   1.00%', '   3.00%'), done=lidx(S(4), '丢包率     Reno', '这个模拟只体现思路'), b=bars([['Reno · 0.1% 丢包', 0.57, '0.57 MB/s'], ['CUBIC(玩具)· 0.1%', 0.56, '0.56 MB/s'], ['BBR 近似(假设)· 0.1%', 11.86, '11.86 MB/s'], ['链路带宽', 12.5, '12.5 MB/s']], 12.5, mark=[2], done=[0, 1, 3]), kv=KV([['丢包算法', '把每个丢包都当拥塞,降速'], ['基于模型的算法', '按带宽 × RTT 建模,对随机丢包不敏感'], ['这个模拟', '玩具模型,BBR 一栏是假设设定']], ['这个模拟'])),
]
A = mkartw('w53', 53, '网络协议,TCP,拥塞控制,CUBIC,Reno,BBR,Mathis公式,真实验证,动画演示',
    '本机默认 CUBIC(macOS 没有按套接字切换算法的接口);实测 CUBIC 的恢复曲线与公式 W(t) = 0.4·(t − K)³ + W_max 吻合(中位误差 6%);在 100 ms 往返、0.1%~3% 丢包下吞吐是 Reno 公式预测的 1.04~2.73 倍;Reno / CUBIC / BBR 的行为差异用玩具模拟说明思路。',
    'Reno、CUBIC、BBR 到底有什么不同?本机用的是哪一个,它的窗口增长真的符合公式吗?这篇验证 CUBIC 的三次曲线,用 Mathis 公式对比实测吞吐,再用一个明确标注的玩具模拟比较基于丢包和基于测量的两类思路。',
    [('6%', '实测 cwnd 与 CUBIC 公式预测值的相对误差中位数(13 个点)'), ('2.73 倍', '0.3% 丢包、往返 100 ms 时,实测吞吐是 Reno(Mathis 公式)预测的倍数(0.1% 时 2.10 倍,3.0% 时 1.04 倍)'), ('0.7', 'CUBIC 的乘性减小系数 β(Reno 是 0.5),在 w52 里已经测出')],
    [('哪个算法', '<p>本机默认是 CUBIC;macOS 上没有按套接字选择算法的接口,所以没有 Reno / BBR 的实测对照。</p>'),
     ('CUBIC 的曲线', '<p>丢包后窗口按 C·(t − K)³ + W_max 回升,先快后平再快;实测与公式基本吻合。</p>'),
     ('与 Reno 对比', '<p>用 Mathis 公式当作 Reno 的预期吞吐,实测的 CUBIC 在高时延路径上快 1~2.7 倍。</p>'),
     ('BBR 的思路', '<p>玩具模拟说明:基于丢包的算法在随机丢包多的链路上吞吐被压得很低,基于带宽 / RTT 测量的算法不受影响。BBR 一栏是假设设定,不是实测。</p>')],
    steps,
    [ENV_W + '。第二、三节在 lo0 上,往返 100 ms 和随机丢包由 netlab 注入;cwnd 来自 TCP_CONNECTION_INFO 的 10 ms 采样,丢包随机,每次运行的曲线不同;CUBIC 公式的 C = 0.4、β = 0.7 取自 RFC 8312;第四节是玩具模拟,其中的 BBR 一栏是按假设直接设定的,不是模拟结果',
     '没有验证:Reno 和 BBR 的实测(本机不能按套接字切换);CUBIC 在 TCP 友好区域的行为;BBR 的带宽 / RTT 估计、公平性与排队;ECN 对拥塞控制的影响;更长时间尺度下的稳态吞吐'],
    '拥塞控制算法')
